&= -\frac{1}{1-\omega^3} - \frac{1}{(\omega^3)^{k+1}(1-\omega^3)}.
\end{align*}
Then integrate both sides term by term (exchanging the order of summation and integration),
\begin{align*}
\sum_{k=1}^{1728} \frac{1}{1+\omega^k+\omega^{2k}+\omega^{3k}}
&= -\int\frac{\mathrm{d}x}{1+\omega^x+\omega^{2x}+\omega^{3x}} \\
&= -\int \sum_{k=0}^\infty -\frac{\omega^{3k}}{1-\omega^3}\left(\omega^x\right)^{k} \ \mathrm{d}x.
\end{align*}
The integral evaluates to:
\begin{align*}
\sum_{k=0}^\infty \frac{1}{1-\omega^3}\int x^k \ \omega^{3k} \ \mathrm{d}x
&= \frac{1}{1-\omega^3} \int \frac{x}{(1-\omega^3)(1-\omega^x)} \ \mathrm{d}x.
\end{align*}
Let $z = 1-x$. Multiplying both sides by $(1-\omega^3)$ and integrating from $0$ to $2$, we have
\begin{align*}
&\int_0^2 \left(z - z^2 + z^3 - \cdots \omega^{-3(2-z)} + \omega^{-6(2-z)} + \omega^{-9(2-z)}\right) \ \mathrm{d}z \\
&= 2\int_0^2 (z - z^2 + \omega^{-3z} - \omega^{-6z} - \omega^{-9z}) \ \mathrm{d}z \\
&= 2\left[\tfrac{1}{2}z^2 - \tfrac{1}{3}z^3 + C\left(-\tfrac{1}{\omega^3}\right)z - C\left(-\tfrac{1}{\omega^6}\right) z - C\left(-\tfrac{1}{\omega^9}\right)z\right]\bigr|^2 \\
&= 2\left[ \tfrac{1}{6}(8-8)\right] \\
&= \frac{4}{3}.
\end{align*}
Since there is no constant term inside the sum in our original expression, the contributor to the sum starting from $k=1$ is smaller by a factor of $-\omega^{-3}$. So we get:
\begin{align*}
\sum_{k=1}^{1728} \frac{1}{1+\omega^k+\omega^{2k}+\omega^{3k}}
&= \color{blue}{\frac{4}{3}\omega^{-3}} \sum_{k=1}^{1728} \omega^k \\
&= \color{blue}{\frac{4}{3}\omega^{-3}} \cdot \frac{1-\omega^{1729}}{1-\omega} \\
&= -\color{blue}{\frac{4}{3(1-\omega)e^{2\pi i/1729}}} \\
